local T = ...
local test, eq, ok = T.test, T.eq, T.ok

-- gap num:226:41:1, written by an automated writer
test("breakit Drive.Trade: late trade complete after a cancelled trade does not pay the driver", function()
    local w = T.newWorld()
    local d = T.driver(w, T.BEA)
    local r = T.rider(w, T.TESTCHAR, { spot = "Ratchet" })
    T.settle(w)
    T.goOnline(d, { price = 5000 })
    w:advance(1)
    w:openTrade(r, d)
    w:tradeMoney(r, 5000)
    w:advance(0.2)
    w:tradeCancel(r)
    w:advance(5.5)
    local msg = d.env.ERR_TRADE_COMPLETE
    if type(msg) ~= "string" or msg == "" then msg = "Trade complete." end
    d:fire("UI_INFO_MESSAGE", 0, msg)
    w:advance(0.4)
    ok(not d:said("gave you"), "a late trade complete message after a cancel does not record a payment")
    T.clean(w)
end)
